package ktanesolver.module.modded.regular.fourcardmonte;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class FourCardMonteSolverTest{@Test void solvesFullRound(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");@SuppressWarnings("unchecked")FourCardMonteOutput o=((SolveSuccess<FourCardMonteOutput>)new FourCardMonteSolver().solve(new RoundEntity(),b,new ModuleEntity(),new FourCardMonteInput(List.of("Ace of Spades","King of Spades","Queen of Spades","Jack of Spades"),List.of("red","blue","green","black"),List.of(1,2,3,4),600,400,10,1,"0123456789",false,false,false,false,false,false))).output();assertThat(o.coinPosition()).isEqualTo(3);assertThat(o.payment()).matches("\\d{3}\\.\\d{2}");}}
